# Check if a given path is valid and does not contain directory traversal characters
def is_valid_path(path: str) -> bool:
    return not any(part in ['..', './', '/'] for part in path.split('/'))

# Example usage
print(is_valid_path("safe_directory/secret_file.txt"))  # Expected: True
print(is_valid_path("../unsafe_directory/secret_file.txt"))  # Expected: False
